import pytest
from django.db.backends.postgresql.client import DatabaseClient


class DummyConnection:
    settings_dict = {}


def test_postgresql_runshell_uses_os_environ_when_no_custom_env(monkeypatch):
    client = DatabaseClient(DummyConnection())

    captured = {}

    def fake_execvp(name, args):
        captured["name"] = name
        captured["args"] = args

    def fake_execvpe(name, args, env):
        captured["name"] = name
        captured["args"] = args
        captured["env"] = env

    monkeypatch.setattr(os, "execvp", fake_execvp)
    monkeypatch.setattr(os, "execvpe", fake_execvpe)

    old_path = os.environ.get("PATH")
    monkeypatch.setenv("PATH", "expected-path-from-os-environ")

    try:
        client.runshell()
    except Exception as exc:
        pytest.fail(f"runshell() unexpectedly raised {exc!r}")

    assert "name" in captured, "runshell() should invoke an os.exec* function"
    assert captured["name"] == "psql"
    assert captured["args"][0] == "psql"
    assert "env" not in captured, "runshell() should not pass an empty env; it should rely on os.environ when no custom env is needed"

    if old_path is not None:
        assert os.enviro…

